CREATE OR REPLACE FUNCTION public.finance_create_refund(p_order uuid, p_item uuid, p_actor uuid, p_amount bigint, p_reason text, p_hash text, p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ DECLARE o public.orders; r public.customer_refunds; committed bigint; ceiling bigint; BEGIN PERFORM public.finance_assert_admin(p_actor); IF p_amount IS NULL OR p_reason IS NULL OR p_hash IS NULL OR p_key IS NULL OR length(p_key)<8 OR p_amount<=0 OR length(trim(p_reason))<5 OR p_hash !~ '^[a-f0-9]{64}$' THEN RAISE EXCEPTION 'Invalid refund'; END IF; SELECT * INTO o FROM public.orders WHERE id=p_order FOR UPDATE; IF NOT FOUND OR o.user_id IS NULL OR NOT (o.status IN ('paid','preparing','separated','shipped','awaiting_pickup','cards_pending_delivery','delivered') OR (o.status='cancellation_requested' AND o.pre_cancel_status IN ('paid','preparing','separated','shipped','awaiting_pickup','cards_pending_delivery','delivered')) OR o.payment_paid_at IS NOT NULL OR o.finance_settled_at IS NOT NULL) THEN RAISE EXCEPTION 'Order has no confirmed payment'; END IF; SELECT * INTO r FROM public.customer_refunds WHERE operation_key=p_key; IF FOUND THEN IF r.order_id<>p_order OR r.amount_cents<>p_amount OR r.item_id IS DISTINCT FROM p_item OR r.created_by<>p_actor OR r.reason<>p_reason THEN RAISE EXCEPTION 'Idempotency conflict'; END IF; RETURN to_jsonb(r)-'token_hash'; END IF; SELECT coalesce(sum(amount_cents-external_confirmed_cents),0) INTO committed FROM public.customer_refunds WHERE order_id=p_order AND status NOT IN ('declined','revoked','refunded','credited'); ceiling:=o.total_cents-coalesce(o.refunded_cents,0)-committed; IF ceiling IS NULL OR ceiling<=0 OR p_amount>ceiling THEN RAISE EXCEPTION 'Refund exceeds remaining paid amount'; END IF; IF p_item IS NOT NULL THEN SELECT round(unit_price_cents::numeric*quantity*greatest(0,1-coalesce(o.discount_cents,0)::numeric/nullif(o.subtotal_cents,0))) INTO ceiling FROM public.order_items WHERE id=p_item AND order_id=p_order; IF ceiling IS NULL THEN RAISE EXCEPTION 'Item not in order'; END IF; SELECT coalesce(sum(amount_cents),0) INTO committed FROM public.customer_refunds WHERE item_id=p_item AND status NOT IN ('declined','revoked'); IF p_amount>ceiling-committed-greatest(0,coalesce((SELECT refund_cents FROM public.order_items WHERE id=p_item),0)-coalesce((SELECT sum(amount_cents) FROM public.customer_refunds WHERE item_id=p_item AND status IN ('refunded','credited')),0)) THEN RAISE EXCEPTION 'Refund exceeds item allocation'; END IF; END IF; INSERT INTO public.customer_refunds(user_id,order_id,item_id,amount_cents,reason,token_hash,token_expires_at,created_by,operation_key,provider_id) VALUES(o.user_id,o.id,p_item,p_amount,p_reason,p_hash,now()+interval '7 days',p_actor,p_key,o.mercadopago_payment_id) RETURNING * INTO r; INSERT INTO public.customer_finance_audit(refund_id,order_id,user_id,actor_id,action,amount_cents,reason) VALUES(r.id,o.id,o.user_id,p_actor,'refund_created',p_amount,p_reason); RETURN to_jsonb(r)-'token_hash'; END $function$;